cards = {"docs": 1000000, "terms": 50000}
sels = {"scan-docs": 1.0, "term-lookup": 0.001}
plans = {
    "scan-then-filter": cards["docs"] * sels["scan-docs"],
    "index-then-fetch": cards["terms"] * sels["term-lookup"] * 10,
}
best = min(plans, key=plans.get)
print("plan costs:", plans, "-> best:", best)
assert best == "index-then-fetch"

parts = {0: [], 1: [], 2: []}
for doc_id in range(30):
    parts[hash(f"doc-{doc_id}") % 3].append(doc_id)
sizes = [len(v) for v in parts.values()]
print("partition sizes:", sizes)
assert sum(sizes) == 30 and max(sizes) - min(sizes) <= 8

workers = [{1: ["a"], 2: ["b"]}, {1: ["c"], 3: ["d"]}]
inbox = {}
for w in workers:
    for key, rows in w.items():
        inbox.setdefault(key % 2, []).extend(rows)
print("after shuffle:", inbox)
assert sorted(inbox[1]) == ["a", "c", "d"] and inbox[0] == ["b"]
